border-line px-3 py-2.5 text-sm"><span class="text-[11px] font-normal text-muted">Choose a one-time initial password and share it through your approved secure channel.</span></label><label class="grid gap-1.5 text-xs font-medium sm:col-span-2">Role<select name="Role" class="rounded-lg border border-line px-3 py-2.5 text-sm"><option value="Staff" selected>Staff</option><option value="Admin">Admin — elevated access</option></select></label></div><div class="mt-6 flex justify-end gap-2"><button type="button" onclick="document.getElementById('create-staff-dialog').close()" class="rounded-lg border border-line px-4 py-2.5 text-sm font-semibold">Cancel</button><button type="submit" class="rounded-lg bg-ink px-4 py-2.5 text-sm font-semibold text-white hover:bg-accent">Create account</button></div></form></dialog>
<dialog id="access-confirm-dialog" class="w-[min(480px,calc(100%-2rem))] rounded-2xl border border-line bg-white p-6 text-ink shadow-2xl"><div class="flex items-start gap-3"><span class="material-symbols-outlined rounded-xl bg-amber-50 p-2 text-amber-700" aria-hidden="true">shield</span><div><h2 id="access-confirm-title" class="text-lg font-semibold">Confirm access change</h2><p id="access-confirm-copy" class="mt-2 text-sm leading-6 text-muted"></p></div></div><p class="mt-4 rounded-lg bg-canvas p-3 text-xs leading-5 text-muted">AuthService validates this operation and prevents changes that remove your own or the last active administrator access.</p><div class="mt-5 flex justify-end gap-2"><button type="button" id="access-confirm-cancel" class="rounded-lg border border-line px-4 py-2.5 text-sm font-semibold">Cancel</button><button type="button" id="access-confirm-submit" class="rounded-lg bg-ink px-4 py-2.5 text-sm font-semibold text-white hover:bg-accent">Confirm change</button></div></dialog>
<script>
(()=>{const confirmation=document.getElementById('access-confirm-dialog');let pending=null;document.querySelectorAll('form[data-confirm-action]').forEach(form=>form.addEventListener('submit',event=>{if(form.dataset.confirmed==='yes'){delete form.dataset.confirmed;return;}event.preventDefault();pending=form;const name=form.dataset.person||'this account';const kind=form.dataset.confirmAction;let copy='';if(kind==='role'){const next=form.elements.Role.value;const old=form.dataset.oldRole;if(next===old){pending=null;return;}document.getElementById('access-confirm-title').textContent=next==='Admin'?'Confirm administrator privilege':'Confirm role change';copy=`Change ${name} from ${old} to ${next}? This updates the role claim used by protected APIs.`;}else{copy=`Confirm that ${name} should be ${form.dataset.nextStatus}. This changes sign-in access${form.dataset.nextStatus==='deactivated'?' and revokes active refresh tokens':''}.`;}document.getElementById('access-confirm-copy').textContent=copy;confirmation.showModal();}));document.getElementById('access-confirm-cancel').addEventListener('click',()=>{pending=null;confirmation.close();});document.getElementById('access-confirm-submit').addEventListener('click',()=>{if(!pending)return;const form=pending;pending=null;confirmation.close();if(form.id==='create-staff-form'){form.dataset.adminConfirmed='yes';}else{form.dataset.confirmed='yes';}form.requestSubmit();});document.getElementById('create-staff-form').addEventListener('submit',event=>{const role=event.currentTarget.elements.Role.value;if(role==='Admin'&&!event.currentTarget.dataset.adminConfirmed){event.preventDefault();pending=event.currentTarget;document.getElementById('access-confirm-title').textContent='Confirm administrator privilege';document.getElementById('access-confirm-copy').textContent='Create this account with the Admin role? Administrators can access all gateway routes protected by the AdminOnly policy.';confirmation.showModal();}});})();
</script></body></html>
